 private UUID post(String ref,String amount,boolean opening){BigDecimal value=new BigDecimal(amount);var cmd=new JournalCommand(UUID.randomUUID(),ref,opening?DAY:DAY.plusDays(1),"Synthetic verified source",null,List.of(new Line(bank,value,BigDecimal.ZERO),new Line(capital,BigDecimal.ZERO,value)));var journal=opening?gl.importOpening(maker,cmd):gl.draftManual(maker,cmd);gl.approve(checker,journal.id(),"Independent synthetic source review");return gl.post(checker,journal.id(),opening).id();}
 private StatementDefinition definition(){return new StatementDefinition(1,1,StatementDefinition.Kind.BALANCE_SHEET,"Synthetic financial position","Hali ya fedha ya majaribio",List.of(new StatementDefinition.Row("BANK","Bank","Benki",StatementDefinition.RowKind.ACCOUNT_GROUP,StatementDefinition.Section.ASSETS,StatementDefinition.Unit.TZS,List.of(bank),StatementDefinition.Sign.DEBIT_POSITIVE,null,null,null,true,false,false,null),new StatementDefinition.Row("CAPITAL","Capital","Mtaji",StatementDefinition.RowKind.ACCOUNT_GROUP,StatementDefinition.Section.EQUITY,StatementDefinition.Unit.TZS,List.of(capital),StatementDefinition.Sign.CREDIT_POSITIVE,null,null,null,true,false,false,null)),List.of(),false);}
 private UUID sample(String language){return sample(language,DAY,END);}
 private UUID sample(String language,LocalDate from,LocalDate through){var definition=OperationalReportDefinition.standard(OperationalReportDefinition.Dataset.DISBURSEMENTS,language);if(language.equals("sw")){var columns=new ArrayList<>(definition.columns());Collections.reverse(columns);definition=new OperationalReportDefinition(1,definition.dataset(),definition.title(),definition.footer(),language,true,columns,definition.filters(),definition.sorts(),definition.groups(),definition.totals(),false);}UUID template=templates.save(definition,null,true,maker);templates.publish(template,checker);UUID id=runs.request(maker,new Request(UUID.randomUUID(),template,from,through,now,Set.of(OperationalReportExportService.Format.CSV),null,null));generator.generate(worker.claim().orElseThrow());runs.approve(id,"Independent synthetic layout acceptance",checker);return id;}
 private AppUserPrincipal operator(String branch){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO members(id,sacco_id,station_id,member_no,staff_no,full_name,status,position,created_at,is_member,staff_access_status,password_hash) VALUES(?,?,?,?,?,'Synthetic H officer','ACTIVE','MANAGER',now(),false,'ACTIVE','test-only')",id,institution,branch,id.toString(),id.toString());var member=Member.builder().id(id).saccoId(institution).stationId(branch).memberNo(id.toString()).staffNo(id.toString()).fullName("Synthetic H officer").position(Position.MANAGER).status(MemberStatus.ACTIVE).staffAccessStatus(StaffAccessStatus.ACTIVE).build();when(directory.find(id)).thenReturn(Optional.of(member));return new AppUserPrincipal(member,EnumSet.allOf(UserClaim.class),true);}
 private Proposal proposal(){return new Proposal(UUID.randomUUID(),output,first,second,"Synthetic release proposal only");}
 private UUID approvedRelease(){UUID id=releases.propose(maker,proposal());releases.decide(accountant,id,Stage.ACCOUNTANT,true,"Synthetic accountant acceptance");releases.decide(compliance,id,Stage.COMPLIANCE,true,"Synthetic compliance acceptance");releases.decide(staff,id,Stage.STAFF,true,"Synthetic staff acceptance");return id;}
 @Test void finalOutputsRetainSameExactResultAndAllThreeChecksummedFormats(){var capture=outputs.get(maker,output);assertThat(capture.result().reconciliations().get("CASH_CLOSING")).isEqualByComparingTo("1001.02");assertThat(capture.sourceChecksum()).isEqualTo(statements.verifiedResultDigest(maker,result));assertThat(outputs.artifacts(maker,output)).hasSize(3);for(var artifact:outputs.artifacts(maker,output)){var downloaded=outputs.download(maker,output,artifact.id());assertThat(ReportRunService.sha256(downloaded.bytes())).isEqualTo(artifact.checksum());}assertThat(outputs.capture(maker,result,new Layout(1,"en",false,false))).isEqualTo(output);assertThatThrownBy(()->jdbc.update("DELETE FROM statement_output_artifacts WHERE output_id=?",output)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void separateIndependentDecisionsGateTheExactPolicyAndScope(){UUID id=releases.propose(maker,proposal());assertThatThrownBy(()->tx.executeWithoutResult(s->gate.requireLiveRelease(maker,policy,1))).hasMessage("accounting.release.error.restricted");assertThatThrownBy(()->releases.decide(maker,id,Stage.ACCOUNTANT,true,"Own acceptance")).hasMessage("accounting.release.error.checker");assertThatThrownBy(()->releases.decide(compliance,id,Stage.COMPLIANCE,true,"Out of sequence")).hasMessage("accounting.release.error.stage");releases.decide(accountant,id,Stage.ACCOUNTANT,true,"Synthetic accountant review");assertThatThrownBy(()->releases.decide(accountant,id,Stage.COMPLIANCE,true,"Repeated reviewer")).hasMessage("accounting.release.error.checker");releases.decide(compliance,id,Stage.COMPLIANCE,true,"Synthetic compliance review");releases.decide(staff,id,Stage.STAFF,true,"Synthetic staff review");assertThat(releases.get(maker,id).getState()).isEqualTo("APPROVED");tx.executeWithoutResult(s->gate.requireLiveRelease(maker,policy,1));assertThatThrownBy(()->tx.executeWithoutResult(s->gate.requireLiveRelease(maker,policy,2))).hasMessage("accounting.release.error.restricted");assertThatThrownBy(()->releases.get(operator("B2"),id)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
 @Test void proposalRetriesAreIdempotentButChangedEvidenceIsRejected(){Proposal proposal=proposal();UUID id=releases.propose(maker,proposal);assertThat(releases.propose(maker,proposal)).isEqualTo(id);assertThatThrownBy(()->releases.propose(maker,new Proposal(proposal.requestKey(),output,first,second,"Changed evidence"))).hasMessage("accounting.release.error.retry");assertThatThrownBy(()->releases.propose(maker,new Proposal(UUID.randomUUID(),output,first,first,"Same layout"))).hasMessage("accounting.release.error.source");}
 @Test void reopeningRevokesReleaseButKeepsEveryFinalArtifactByte(){UUID id=approvedRelease();var artifact=outputs.artifacts(maker,output).getFirst();byte[] before=outputs.download(maker,output,artifact.id()).bytes();now=now.plusMinutes(1);UUID reopen=closing.proposeClose(accountant,period,"Synthetic reviewed correction",true);closing.approveClose(compliance,reopen,"Independent reopening evidence");assertThat(releases.get(maker,id).getState()).isEqualTo("INVALIDATED");assertThatThrownBy(()->tx.executeWithoutResult(s->gate.requireLiveRelease(maker,policy,1))).hasMessage("accounting.release.error.restricted");assertThat(outputs.download(maker,output,artifact.id()).bytes()).isEqualTo(before);assertThatThrownBy(()->releases.propose(maker,proposal())).hasMessage("reconciliation.error.approvalRequired");}
 @Test void retirementRevokesReleaseAndCannotRewriteRetainedEvidence(){UUID id=approvedRelease();String checksum=releases.get(maker,id).checksum();statements.retire(checker,version);assertThat(releases.get(maker,id).getState()).isEqualTo("INVALIDATED");assertThat(releases.get(maker,id).checksum()).isEqualTo(checksum);assertThatThrownBy(()->tx.executeWithoutResult(s->gate.requireLiveRelease(maker,policy,1))).hasMessage("accounting.release.error.restricted");assertThatThrownBy(()->jdbc.update("UPDATE accounting_release_decisions SET approved=false WHERE release_id=?",id)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void auditFailureRollsBackReleaseDecisionAndAllowsExactRetry(){UUID id=releases.propose(maker,proposal());doThrow(new IllegalStateException("Synthetic audit failure")).when(audit).log(eq("ACCOUNTING_RELEASE"),eq(id),eq("ACCOUNTANT_APPROVED"),any(),any(),anyMap());assertThatThrownBy(()->releases.decide(accountant,id,Stage.ACCOUNTANT,true,"Synthetic review")).hasMessage("Synthetic audit failure");assertThat(releases.get(maker,id).decisions()).isEmpty();reset(audit);releases.decide(accountant,id,Stage.ACCOUNTANT,true,"Synthetic review");assertThat(releases.get(maker,id).decisions()).hasSize(1);}
