 @Test void concurrentAccountantDecisionsRecordExactlyOneReview()throws Exception{UUID id=releases.propose(maker,proposal());try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->decision(accountant,id));var b=pool.submit(()->decision(operatorForThread(),id));assertThat(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);assertThat(releases.get(maker,id).decisions()).hasSize(1);}}
