 @Test void RenamingAnOtherwiseIdenticalLayoutDoesNotSatisfyTwoLayoutAcceptance(){UUID identical=sample("en");assertThatThrownBy(()->releases.propose(maker,new Proposal(UUID.randomUUID(),output,first,identical,"Synthetic repeated layout"))).hasMessage("accounting.release.error.layouts");}
 @Test void mappingRetirementWaitsForAnAlreadyAuthorizedPostingTransaction()throws Exception{
  UUID id=approvedRelease();var entered=new CountDownLatch(1);var finish=new CountDownLatch(1);
  try(var pool=Executors.newFixedThreadPool(2)){
   var posting=pool.submit(()->tx.executeWithoutResult(s->{gate.requireLiveRelease(maker,policy,1);entered.countDown();try{if(!finish.await(10,TimeUnit.SECONDS))throw new AssertionError("Synthetic posting latch timeout");}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new AssertionError(ex);}}));
   assertThat(entered.await(10,TimeUnit.SECONDS)).isTrue();var retirement=pool.submit(()->statements.retire(checker,version));
   assertThatThrownBy(()->retirement.get(300,TimeUnit.MILLISECONDS)).isInstanceOf(TimeoutException.class);finish.countDown();posting.get(10,TimeUnit.SECONDS);retirement.get(10,TimeUnit.SECONDS);assertThat(releases.get(maker,id).getState()).isEqualTo("INVALIDATED");
  }finally{finish.countDown();}
 }
