  UUID laterResult=statements.finalize(maker,version,close,null);UUID laterOutput=outputs.capture(maker,laterResult,new Layout(1,"en",false,false));outputs.review(checker,laterOutput,"Independent later output review");UUID a=sample("en",from,through),b=sample("sw",from,through);UUID laterRelease=releases.propose(maker,new Proposal(UUID.randomUUID(),laterOutput,a,b,"Synthetic later release"));releases.decide(accountant,laterRelease,Stage.ACCOUNTANT,true,"Synthetic later accountant");releases.decide(compliance,laterRelease,Stage.COMPLIANCE,true,"Synthetic later compliance");releases.decide(staff,laterRelease,Stage.STAFF,true,"Synthetic later staff");var artifact=outputs.artifacts(maker,laterOutput).getFirst();byte[] before=outputs.download(maker,laterOutput,artifact.id()).bytes();
